+        <VectorSearchTool />
       </div>
-
-      {q && (
-        <div className="max-w-3xl mx-auto">
-          <h2 className="font-arabic text-xl font-semibold mb-4">
-            نتائج البحث عن: {q}
-          </h2>
-          <SearchResults query={q} initialType={type || "all"} />
-        </div>
-      )}
     </main>
   );
 }
